using Bovis.Interfaces;
using Bovis.Interfaces.Configuration;
using Bovis.Services;
using Bovis.Services.Renderer;
using Microsoft.AspNetCore.Cors;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Routing.Constraints;

namespace Bovis.Web.Views
{

    /// <summary>
    /// MVC controller that renders service data as HTML, images, or PDFs.
    /// It supports optional query parameters for image size/scale and can
    /// return results either as raw files or as JSON payloads containing
    /// base64‑encoded images and image‑map data.
    /// </summary>
    [PublicRoute("/render")]
    [TypeFilter(typeof(RedactedExceptionFilter))]
    [EnableCors("Bovis.Render.CorsPolicy")]
    public class RenderController : Microsoft.AspNetCore.Mvc.Controller
    {
        // Mapping from format identifiers to MIME types.
        static readonly Dictionary<string, string> s_typeToMime = new()
        {
            {"pdf","application/pdf"},
            {"xps","application/xps"},
            {"png","image/png"},
            {"svg","image/svg+xml"},
        };

        /// <summary>
        /// Entry point for rendering requests.
        /// </summary>
        /// <param name="bohrlochRenderer">Renderer for borehole images, injected from the service container.</param>
        /// <param name="data">Data source for retrieving borehole information.</param>
        /// <param name="config">Configuration store for service definitions.</param>
        /// <param name="sid">Service identifier.</param>
        /// <param name="id">Borehole identifier.</param>
        /// <param name="format">Desired output format (e.g., png, pdf).</param>
        /// <param name="map">If set to "json", returns a JSON payload with image map data.</param>
        /// <param name="pic_height">Optional override for picture height.</param>
        /// <param name="pic_scale">Optional override for picture scale.</param>
        /// <param name="pic_width">Optional override for picture width.</param>
        /// <returns>An <see cref="ActionResult"/> containing the rendered output.</returns>
        [HttpGet]
        public async Task<ActionResult> IndexAsync([FromServices] BohrlochRenderer bohrlochRenderer, [FromServices] Bovis.Interfaces.IBovisDataSource data, [FromServices] IConfigurationStore config, string sid, string id, string? format, string? map, string? pic_height, string? pic_scale, string? pic_width)
        {
            if (!ModelState.IsValid) return BadRequest(ModelState);

            DbKeyValue Id = (DbKeyValue)id;
            var req = Request;
            IConfigurationStore.AccessMode accessMode = IConfigurationStore.AccessMode.ReadOnly;
            // pic_height überschreibt Werte im BohrlochService. 
            // daher den Service als beschreibbar (nicht aus dem Cache) lesen.
            if ((pic_height != null) || (pic_scale != null)) accessMode = IConfigurationStore.AccessMode.ReadWrite;

            var obj = config.GetObject<object?>($"services/{sid}", accessMode);
            if (obj == null) return NotFound();

            // Now displatch upon service type of obj
            if (obj is Bovis.Services.HtmlService html)
            {
                return await RenderHTML(data, config, sid, Id, html);
            }
            else if (obj is Bovis.Services.BohrlochService bls)
            {
                // override values in bls with optional query parameters.
                { if (int.TryParse(pic_height, out var pic_height_i)) bls.PicHeight.Data = pic_height; }
                { if (int.TryParse(pic_width, out var pic_width_i)) bls.PicWidth.Data = pic_width; }
                {
                    if (int.TryParse(pic_scale, out var pic_scale_i))
                    {
                        if (pic_scale_i != -1) // -1=Voreinstellung
                        {
                            bls.PicScale = pic_scale_i;
                        }
                    }
                }
                return await RenderImage(bohrlochRenderer, data, config, format, map, Id, bls);
            }
            else
                return NotFound();
        }

