        /// <param name="dataSource">Data source for borehole data.</param>
        /// <param name="configStore">Configuration store for renderer settings.</param>
        /// <param name="format">Requested output format.</param>
        /// <param name="map">If "json", returns a JSON payload with image map information.</param>
        /// <param name="Id">Borehole identifier.</param>
        /// <param name="bohrlochService">Service containing rendering parameters.</param>
        /// <returns>An <see cref="ActionResult"/> containing the rendered image or JSON.</returns>
